create schema if not exists identity;
create schema if not exists app;
do $$ begin if not exists(select from pg_roles where rolname='fitcore_app') then create role fitcore_app login nosuperuser nobypassrls; end if; end $$;
create table identity.users(id uuid primary key default gen_random_uuid(), email text not null unique, name text not null, password_hash text not null, verified_at timestamptz, created_at timestamptz not null default now());
create table identity.sessions(token_hash text primary key, user_id uuid not null references identity.users on delete cascade, expires_at timestamptz not null, created_at timestamptz not null default now());
create table identity.tokens(token_hash text primary key, user_id uuid references identity.users on delete cascade, purpose text not null check(purpose in ('verify','reset','invite')), payload jsonb not null default '{}', expires_at timestamptz not null, used_at timestamptz);
create table identity.rate_limits(key text primary key, hits integer not null, window_at timestamptz not null default now());
create table app.tenants(id uuid primary key default gen_random_uuid(), name text not null, timezone text not null default 'America/Sao_Paulo', created_at timestamptz not null default now());
create table identity.tenant_members(tenant_id uuid references app.tenants on delete cascade, user_id uuid references identity.users on delete cascade, role text not null check(role in ('owner','trainer','student')), primary key(tenant_id,user_id));
create table app.subscription_plans(id text primary key, name text not null, price_cents integer not null check(price_cents>=0), currency text not null default 'BRL', student_limit integer not null check(student_limit>0), monthly_token_limit integer not null check(monthly_token_limit>0), stripe_price_id text, enabled boolean not null default true);
insert into app.subscription_plans values ('essential','Essencial',7900,'BRL',20,100000,null,true),('professional','Profissional',14900,'BRL',60,300000,null,true),('studio','Studio',29900,'BRL',150,1000000,null,true);
create table app.subscriptions(tenant_id uuid primary key references app.tenants, plan_id text not null references app.subscription_plans, status text not null check(status in ('trialing','active','past_due','canceled','unpaid','incomplete','incomplete_expired','paused')), trial_ends_at timestamptz, stripe_customer_id text unique, stripe_subscription_id text unique, updated_at timestamptz not null default now());
create table app.students(id uuid primary key default gen_random_uuid(), tenant_id uuid not null references app.tenants, user_id uuid references identity.users, name text not null, email text not null, goal text not null, experience text not null, days_per_week integer not null check(days_per_week between 1 and 7), equipment text[] not null default '{}', limitations text not null default '', automation_enabled boolean not null default false, status text not null default 'active' check(status in ('active','archived')), revision integer not null default 1, created_at timestamptz not null default now(), unique(id,tenant_id),unique(tenant_id,email));
create table app.exercises(id uuid primary key default gen_random_uuid(), tenant_id uuid not null references app.tenants, name text not null, muscle text not null, equipment text not null, instructions text not null, enabled boolean not null default true, unique(id,tenant_id));
create table app.ai_agents(id uuid primary key default gen_random_uuid(), tenant_id uuid not null references app.tenants, name text not null, current_version integer not null default 1, unique(id,tenant_id));
create table app.ai_agent_versions(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references app.tenants, agent_id uuid not null, version integer not null, rules jsonb not null check(jsonb_typeof(rules)='object'), author_id uuid not null references identity.users, created_at timestamptz not null default now(),foreign key(agent_id,tenant_id) references app.ai_agents(id,tenant_id),unique(agent_id,version),unique(id,tenant_id));
create table app.assessments(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references app.tenants,student_id uuid not null,author_id uuid not null references identity.users, measured_on date not null, weight_kg numeric(6,2) not null check(weight_kg>0 and weight_kg<=600),height_cm numeric(5,2) not null check(height_cm>0 and height_cm<=250), waist_cm numeric(6,2) check(waist_cm>0 and waist_cm<=400), new_pain boolean not null default false, notes text not null default '', created_at timestamptz not null default now(), foreign key(student_id,tenant_id) references app.students(id,tenant_id),unique(id,tenant_id));
create table app.workout_plans(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references app.tenants,student_id uuid not null, current_version_id uuid, created_at timestamptz not null default now(), foreign key(student_id,tenant_id) references app.students(id,tenant_id),unique(id,tenant_id),unique(student_id,tenant_id));
create table app.training_cycles(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references app.tenants,student_id uuid not null, plan_id uuid not null, source_version_id uuid not null,agent_version_id uuid,assessment_id uuid,interval_days integer not null default 45 check(interval_days between 1 and 365),timezone text not null,due_at timestamptz not null,status text not null default 'scheduled' check(status in ('scheduled','awaiting_assessment','incomplete','processing','review','published','suspended','failed','canceled')),reason text,attempts integer not null default 0,next_attempt_at timestamptz not null default now(),lease_until timestamptz, proposal_id uuid,created_at timestamptz not null default now(),foreign key(student_id,tenant_id) references app.students(id,tenant_id),foreign key(plan_id,tenant_id) references app.workout_plans(id,tenant_id),foreign key(agent_version_id,tenant_id) references app.ai_agent_versions(id,tenant_id),unique(id,tenant_id),unique(source_version_id));
create index cycles_due on app.training_cycles(status,due_at,next_attempt_at);
create table app.workout_plan_versions(id uuid primary key default gen_random_uuid(), tenant_id uuid not null references app.tenants,plan_id uuid not null,student_id uuid not null,version integer not null, content jsonb not null check(jsonb_typeof(content)='object'),source text not null check(source in ('manual','ai','restore')),cycle_id uuid unique,agent_version_id uuid,author_id uuid not null references identity.users,reason text not null, published_at timestamptz not null default now(), foreign key(plan_id,tenant_id) references app.workout_plans(id,tenant_id),foreign key(student_id,tenant_id) references app.students(id,tenant_id),foreign key(cycle_id,tenant_id) references app.training_cycles(id,tenant_id),foreign key(agent_version_id,tenant_id) references app.ai_agent_versions(id,tenant_id),unique(plan_id,version),unique(id,tenant_id));
alter table app.workout_plans add foreign key(current_version_id,tenant_id) references app.workout_plan_versions(id,tenant_id);
alter table app.training_cycles add foreign key(source_version_id,tenant_id) references app.workout_plan_versions(id,tenant_id);
create table app.ai_runs(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references app.tenants,student_id uuid not null,cycle_id uuid,model text not null,status text not null check(status in ('reserved','succeeded','failed')),reserved_tokens integer not null, input_tokens integer,output_tokens integer,error_code text,created_at timestamptz not null default now(),foreign key(student_id,tenant_id) references app.students(id,tenant_id),unique(id,tenant_id));
create table app.proposals(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references app.tenants,student_id uuid not null,agent_version_id uuid,cycle_id uuid unique,ai_run_id uuid,content jsonb not null,validation jsonb not null,status text not null check(status in ('valid','blocked','published')),student_revision integer not null,assessment_id uuid,base_version_id uuid, created_at timestamptz not null default now(),foreign key(student_id,tenant_id) references app.students(id,tenant_id),foreign key(agent_version_id,tenant_id) references app.ai_agent_versions(id,tenant_id),foreign key(cycle_id,tenant_id) references app.training_cycles(id,tenant_id),foreign key(ai_run_id,tenant_id) references app.ai_runs(id,tenant_id),unique(id,tenant_id));
create table app.workout_logs(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references app.tenants,student_id uuid not null,version_id uuid not null,request_id uuid not null,sets jsonb not null check(jsonb_typeof(sets)='array'),discomfort boolean not null default false, notes text not null default '',created_at timestamptz not null default now(),foreign key(student_id,tenant_id) references app.students(id,tenant_id),foreign key(version_id,tenant_id) references app.workout_plan_versions(id,tenant_id),unique(student_id,request_id));
create table app.notifications(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references app.tenants,student_id uuid,kind text not null,message text not null,read_at timestamptz,created_at timestamptz not null default now(),foreign key(student_id,tenant_id) references app.students(id,tenant_id));
create table app.audit_logs(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references app.tenants,actor_id uuid not null references identity.users,action text not null,resource_id uuid,metadata jsonb not null default '{}',created_at timestamptz not null default now());
create table app.payment_events(id text primary key,type text not null,tenant_id uuid references app.tenants,processed_at timestamptz not null default now());
create table app.deletion_requests(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references app.tenants,user_id uuid not null references identity.users, status text not null default 'pending',created_at timestamptz not null default now());
create table app.student_consents(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references app.tenants,student_id uuid not null,purpose text not null,granted boolean not null,version text not null,created_at timestamptz not null default now(),foreign key(student_id,tenant_id) references app.students(id,tenant_id));
-- Student row scope is applied in SQL, independently of frontend and HTTP handlers.
create function app.is_staff() returns boolean language sql stable as $$select coalesce(current_setting('app.role',true),'') in ('owner','trainer')$$;
create function app.tenant() returns uuid language sql stable as $$select nullif(current_setting('app.tenant_id',true),'')::uuid$$;
create function app.student() returns uuid language sql stable as $$select nullif(current_setting('app.student_id',true),'')::uuid$$;
do $$ declare t text; begin
 foreach t in array array['students','assessments','workout_plans','workout_plan_versions','training_cycles','proposals','workout_logs','notifications','student_consents'] loop
  execute format('alter table app.%I enable row level security',t);
  execute format('alter table app.%I force row level security',t);
  if t='students' then
   execute format('create policy tenant_scope on app.%I using(tenant_id=app.tenant() and (app.is_staff() or id=app.student())) with check(tenant_id=app.tenant() and (app.is_staff() or id=app.student()))',t);
  else
   execute format('create policy tenant_scope on app.%I using(tenant_id=app.tenant() and (app.is_staff() or student_id=app.student())) with check(tenant_id=app.tenant() and (app.is_staff() or student_id=app.student()))',t);
  end if;
 end loop;
 foreach t in array array['exercises','ai_agents','ai_agent_versions','ai_runs','subscriptions','audit_logs','deletion_requests'] loop
  execute format('alter table app.%I enable row level security',t);
  execute format('alter table app.%I force row level security',t);
  execute format('create policy tenant_scope on app.%I using(tenant_id=app.tenant() and app.is_staff()) with check(tenant_id=app.tenant() and app.is_staff())',t);
 end loop;
end $$;
alter table app.tenants enable row level security;
alter table app.tenants force row level security;
create policy tenant_scope on app.tenants using(id=app.tenant()) with check(id=app.tenant() and app.is_staff());
grant usage on schema app to fitcore_app;
grant select,insert,update,delete on all tables in schema app to fitcore_app;
revoke all on app.payment_events from fitcore_app;
revoke insert,update,delete on app.subscription_plans,app.subscriptions from fitcore_app;
revoke update,delete on app.workout_plan_versions,app.ai_agent_versions,app.audit_logs,app.assessments,app.student_consents from fitcore_app;
-- Even accidental updates through an elevated connection must not mutate history.
create function app.immutable() returns trigger language plpgsql as $$begin raise exception 'immutable_record'; end$$;
create trigger immutable_versions before update or delete on app.workout_plan_versions for each row execute function app.immutable();
create trigger immutable_agents before update or delete on app.ai_agent_versions for each row execute function app.immutable();
create trigger immutable_audit before update or delete on app.audit_logs for each row execute function app.immutable();
create index students_tenant on app.students(tenant_id,status,created_at);
create index assessments_student on app.assessments(tenant_id,student_id,measured_on desc,created_at desc);
create index logs_student on app.workout_logs(tenant_id,student_id,created_at desc);
create index audit_tenant on app.audit_logs(tenant_id,created_at desc);
